@RelationalLimit.sem_lift_lub_of_joint_chain
     : forall (M : Type -> Type) (MI : Measure.SemanticMeasure M),
       @Measure.SemanticMeasureCoreLaws M MI ->
       @Measure.SemanticMeasureBindLaws M MI ->
       @AE.SemanticMeasureAELiftLaws M MI ->
       forall MO : @Omega.SemanticOmega M MI,
       @Omega.SemanticOmegaLaws M MI MO ->
       @Omega.SemanticOmegaAELaws M MI MO ->
       forall (A B : Type) (R : A -> B -> Prop) (left : nat -> M A) (right : nat -> M B)
         (joints : nat -> M (A * B)%type) (out1 : M A) (out2 : M B),
       @Omega.sem_increasing M MI MO (A * B) joints ->
       @Omega.sem_lub M MI MO A left out1 ->
       @Omega.sem_lub M MI MO B right out2 ->
       (forall n : nat,
        @Measure.sem_eq M MI A
          (@Measure.sem_bind M MI (A * B) A (joints n)
             (fun p : A * B => @Measure.sem_ret M MI A (@fst A B p))) (left n)) ->
       (forall n : nat,
        @Measure.sem_eq M MI B
          (@Measure.sem_bind M MI (A * B) B (joints n)
             (fun p : A * B => @Measure.sem_ret M MI B (@snd A B p))) (right n)) ->
       (forall n : nat,
        @Measure.sem_ae M MI (A * B) (joints n) (fun p : A * B => R (@fst A B p) (@snd A B p))) ->
       @Measure.sem_lift M MI A B R out1 out2

CountableRelationalLimit.oval_coupled_lub_of_countable_limits
     : forall (R : reals.Real.type) (A B : Type) (T : A -> B -> Prop)
         (c : nat -> Expectation.OmegaVal R A) (d : nat -> Expectation.OmegaVal R B)
         (Hc : @Expectation.oval_increasing R A c) (Hd : @Expectation.oval_increasing R B d),
       @Countable.oval_countably_supported R A (@Expectation.oval_lub R A c Hc) ->
       @Countable.oval_countably_supported R B (@Expectation.oval_lub R B d Hd) ->
       (forall n : nat, @Coupling.oval_coupled R A B T (c n) (d n)) ->
       @Coupling.oval_coupled R A B T (@Expectation.oval_lub R A c Hc)
         (@Expectation.oval_lub R B d Hd)

